/*
 * This product's own brand, in the runtime's own page.
 *
 * The embedded page is upstream's and it says "deepseek HARNESS" in its
 * sidebar and draws a whale on its conversation hero. Neither is wrong about
 * what the runtime is; both are wrong about what an operator is looking at,
 * because the window around them says FA Foundry and the sessions they open
 * write into this product's store.
 *
 * The runtime already has the seam for this. `dsh-client-ui-brand-official`
 * fills three named slots and nothing more, and a slot is a declaration any
 * client plugin in the profile can occupy. So this is not a patch of upstream
 * and not a selector hunt in its markup: it is the same three registrations,
 * from a bundle that is already in the profile because the period tools are in
 * it.
 *
 * The module-loader envelope, the `inject` list and the nested `slots.inject`
 * shape below are copied from that package's own `client.js`. Copying rather
 * than inventing means an upstream change to the contract shows up as a
 * bundle that fails to compose, with a message, rather than as a sidebar that
 * quietly goes back to saying deepseek.
 *
 * The mark travels as a data URI. The page carries no CSP of its own -- checked
 * on a running build, no header and no meta -- and the alternative is serving a
 * file over a path this bundle would have to know the shape of.
 */
window.__ModuleLoader__.load({
  id: 'finance-skill-foundry-dsh',
  factory: (require) => {
    const module = { exports: {} };
    const exports = module.exports;
    Object.defineProperty(exports, Symbol.toStringTag, { value: 'Module' });
    const jsx = require('react/jsx-runtime');

    /** The operator's own artwork, trimmed to the figure. 197x256. */
    const MARK = 'data:image/png;base64,';

    /**
     * The mark, in one colour, at whatever size the host slot asks for.
     *
     * White rather than the artwork's own three gradients, and that is about
     * how often it appears rather than about how it looks. The coloured mark
     * is the product's identity and the window's header is where it is said;
     * repeating it inside the embedded page put the same gradients on screen
     * twice more, within one glance of each other. One of them carries the
     * identity and the other two say whose rail and whose hero this is, which
     * a silhouette does just as well.
     *
     * Derived from the same bytes rather than embedded a second time.
     * `brightness(0)` takes every pixel to black and `invert(1)` takes it to
     * white, both leaving alpha alone -- so there is still one artwork here,
     * and replacing it recolours this automatically.
     *
     * `size` is a height, not a box: the artwork is taller than it is wide, and
     * forcing it square would letterbox it inside its own padding.
     */
    function BrandMark({ size, className }) {
      const height = typeof size === 'number' ? size : 24;
      return jsx.jsx('img', {
        src: MARK,
        alt: '',
        className,
        style: {
          height: height + 'px',
          width: 'auto',
          display: 'block',
          filter: 'brightness(0) invert(1)',
        },
      });
    }

    /**
     * The sidebar's name slot, deliberately empty.
     *
     * Occupied rather than left to upstream, because leaving it would put the
     * vendor's wordmark back. What it renders is nothing: opening the window
     * used to show this product's mark and name three times over -- the
     * window's own header, this sidebar, and the conversation hero -- and two
     * of those are within 40px of each other. The mark alone still says whose
     * sidebar this is.
     */
    function BrandName() {
      return null;
    }


    /*
     * What a call archived, drawn where the call is.
     *
     * The versions were always there -- `deliverables.jsonl` has held them
     * since the task chain existed -- and reading them meant leaving the
     * conversation for the 交付物 screen. What that screen cannot do is stand a
     * version next to the question that produced it: `cause` is
     * `query-locked:followup-3`, which in a table is a foreign key an operator
     * resolves in their head, and on this row is the sentence directly above.
     *
     * `tool.call.toolview` is keyed on the wire tool name, and our three names
     * are not in the shipped composition, so this is additive: an unclaimed key
     * falls back to the generic row and registering ours takes over nothing.
     *
     * The payload rides `block.meta`, which is what `output.presentationMeta`
     * projected on the host. It is computed only for top-level calls, so a
     * nested one draws the text and no strip -- correct, rather than a strip
     * claiming the call filed nothing.
     */
    const RECEIPT_TOOLS = {
      'emit-brief': '本期结论稿',
      'query-locked': '追问重算',
      'record-reference': '外部引用',
    };

    const KIND_LABEL = { brief: '结论稿', workpaper: '底稿', export: '导出件' };

    /** Twelve characters is identity enough, and the row has no width to spare. */
    function shortSha(sha) {
      const text = String(sha || '');
      return text.length > 12 ? text.slice(0, 12) + '\u2026' : text;
    }

    /** Every text block the tool returned, which is what the model read. */
    function resultText(block) {
      const content = (block && block.content) || [];
      return content
        .filter((part) => part && part.type === 'text' && typeof part.text === 'string')
        .map((part) => part.text)
        .join('\n')
        .trim();
    }

    /**
     * The receipt, read defensively off a node this bundle does not own.
     *
     * Every branch is a real state rather than paranoia: a running call has no
     * `meta`, a nested call is never projected, and an older `foundry` on the
     * PATH comes through `index.js`'s degrade path with no receipt at all.
     */
    function receiptOf(block) {
      const meta = block && block.meta;
      if (!meta || typeof meta !== 'object') return null;
      return Array.isArray(meta.filed) ? meta.filed : null;
    }

    const STRIP = {
      marginTop: 6,
      display: 'flex',
      flexWrap: 'wrap',
      gap: 6,
      alignItems: 'center',
      fontSize: 11,
      lineHeight: 1.4,
    };
    const CHIP = {
      display: 'inline-flex',
      alignItems: 'center',
      gap: 4,
      padding: '1px 7px',
      borderRadius: 999,
      border: '1px solid currentColor',
      whiteSpace: 'nowrap',
    };
    /* The window's own accent, so a receipt reads as this product's. */
    const GOLD = { color: '#b08a3e' };
    const QUIET = { opacity: 0.6 };
    /* A refusal is a designed output here, not a crash, but it is not a result. */
    const REFUSED = { color: '#a8442e' };

    function FiledChip(props) {
      const row = props.row || {};
      const label = KIND_LABEL[row.kind] || row.kind || '版本';
      const sha = shortSha(row.sha256);
      return jsx.jsxs('span', {
        style: Object.assign({}, CHIP, row.appended === false ? QUIET : GOLD),
        children: [
          row.appended === false ? label + ' · 已在册' : label,
          sha ? jsx.jsx('span', { style: QUIET, children: sha }) : null,
        ],
      });
    }

    /**
     * One foundry call, as a turn row.
     *
     * A settled call with an empty receipt is not the same as one that filed
     * nothing worth mentioning. It means the window had no task to file
     * against, and saying so is the only honest thing to draw; silence there
     * would read as success.
     */
    function FoundryRow(props) {
      const block = (props && props.block) || null;
      const settled = Boolean(block) && 'kind' in block;
      const title = RECEIPT_TOOLS[props && props.toolName] || (props && props.toolName) || 'foundry';
      const text = settled ? resultText(block) : '';
      const filed = settled && !block.isError ? receiptOf(block) : null;

      let strip = null;
      if (settled && block.isError) {
        /*
         * Registering this key takes the whole row, including the failures the
         * shipped generic row used to draw. A refusal is the fence working --
         * `not-in-this-window`, a window that is not locked -- and it must not
         * read as an answer just because this bundle owns the row now.
         */
        strip = jsx.jsx('span', {
          style: REFUSED,
          children: '拒绝 · ' + (String((block.error && block.error.code) || '') || '见上'),
        });
      } else if (!settled) {
        strip = jsx.jsx('span', { style: QUIET, children: '正在从锁库算…' });
      } else if (filed && filed.length === 0) {
        strip = jsx.jsx('span', { style: QUIET, children: '未登记 · 这个窗口还没有绑到任务' });
      } else if (filed && filed.length > 0) {
        strip = jsx.jsxs('span', {
          style: { display: 'contents' },
          children: [
            jsx.jsx('span', { style: QUIET, children: '归档' }),
            filed.map((row, index) =>
              jsx.jsx(FiledChip, { row: row }, String((row && row.sha256) || index)),
            ),
          ],
        });
      }

      return jsx.jsxs('div', {
        style: { fontSize: 13, lineHeight: 1.6 },
        children: [
          jsx.jsx('div', {
            style: Object.assign({ fontSize: 11, letterSpacing: '0.04em' }, QUIET),
            children: title,
          }),
          text ? jsx.jsx('div', { style: { whiteSpace: 'pre-wrap' }, children: text }) : null,
          strip ? jsx.jsx('div', { style: STRIP, children: strip }) : null,
        ],
      });
    }

    /** The slot registry, and the panel actions that open and close the rail. */
    const inject = ['slots', 'layout'];

    /**
     * Start with the sidebar closed.
     *
     * This window is not a session browser. It has its own task strip directly
     * above, and the rail's own list is a second navigation for the same
     * conversations -- so the operator opens onto the conversation, and the
     * rail is one click away when they want it.
     *
     * Decided on rendered geometry, and that is the second thing this got
     * wrong. `toggleSidebar` is the only public verb and it toggles, so
     * something has to say which way the sidebar currently is. The frame
     * publishes `data-sidebar-collapsed`, and reading it is a trap: on the
     * first tick after mount it is present, because the panel store has not
     * been hydrated and a width of zero reads as collapsed. A run that trusted
     * it concluded there was nothing to do and stopped, on a sidebar that was
     * about to open. Measuring where the toggle button actually sits cannot be
     * fooled that way -- an unlaid-out element has no box at all, and a rail
     * puts that button near the window's left edge while an open sidebar puts
     * it 280px in.
     *
     * `apply` runs as soon as the `layout` service is provided, which is well
     * before the React root mounts and wires the panel actions to it; until
     * then the verb throws `layout: panel actions not wired (root entry not
     * mounted)`. Hence a poll rather than a single call, bounded so a build
     * that never mounts does not leave a timer running for the life of the
     * page.
     */
    /** Where the toggle sits once the rail is closed, with room either side. */
    const RAIL_EDGE = 150;

    /** Consecutive agreeing measurements before the layout counts as settled. */
    const SETTLED_TICKS = 4;

    function collapseOnce(ctx) {
      if (window.__fndRailArmed) return;
      window.__fndRailArmed = true;
      const started = Date.now();
      let last = null;
      let agreed = 0;
      const timer = setInterval(() => {
        if (Date.now() - started > 15000) return clearInterval(timer);
        const toggle = document.querySelector('[class*="_toggle"]');
        if (!toggle) return;
        const left = toggle.getBoundingClientRect().left;
        // Mounted but not laid out: an element with no box has nothing to say.
        if (toggle.getBoundingClientRect().width === 0) return;
        // Wait for the reading to stop moving before believing it. Both of the
        // states this could act on are transiently wrong in the first frames.
        agreed = last !== null && Math.abs(left - last) < 1 ? agreed + 1 : 0;
        last = left;
        if (agreed < SETTLED_TICKS) return;
        // Settled, and already a rail. Toggling would open it.
        if (left < RAIL_EDGE) return clearInterval(timer);
        try {
          ctx.layout.toggleSidebar();
          clearInterval(timer);
        } catch {
          // The actions are not wired yet. The next tick asks again.
        }
      }, 80);
    }

    /**
     * Shadow the official brand, rather than replace it.
     *
     * These three are single-occupant slots and the official plugin is already
     * in every one of them at priority 0. Registering beside it is refused, in
     * so many words: `single slot "sidebar.brand.mark" already has a
     * registration at priority 0 (registered by z5) -- register at a different
     * priority to shadow it (lowest renders)`. So this registers below it and
     * upstream's occupant stays where it is, unrendered.
     *
     * Shadowing rather than unloading their plugin is the safer half of that
     * choice: nothing here has to reach into another package's composition, and
     * a build where these slots move or disappear loses this product's mark
     * rather than the whole sidebar.
     *
     * The nesting is upstream's own shape and it is load-bearing: each `inject`
     * waits for its slot to be declared before the `register` inside it runs,
     * so a slot a future shell does not declare costs nothing rather than
     * throwing.
     */
    const SHADOW = -1;

    function apply(ctx) {
      ctx.slots.inject('sidebar.brand.mark', () =>
        ctx.slots.inject('sidebar.brand.name', () =>
          ctx.slots.inject('conversation.hero.brand.mark', function* () {
            yield ctx.slots.register({ name: 'sidebar.brand.mark', priority: SHADOW }, BrandMark);
            yield ctx.slots.register({ name: 'sidebar.brand.name', priority: SHADOW }, BrandName);
            yield ctx.slots.register(
              { name: 'conversation.hero.brand.mark', priority: SHADOW },
              BrandMark,
            );
          }),
        ),
      );
      /*
       * Its own `inject`, not nested in the brand chain above. That chain hangs
       * off slots the shell declares; this one is declared by an entry in
       * `conversation.chat.node`, so it arrives on a different schedule, and
       * nesting it would tie a receipt row to whether a sidebar mark exists.
       */
      ctx.slots.inject('tool.call.toolview', function* () {
        for (const toolName of Object.keys(RECEIPT_TOOLS)) {
          yield ctx.slots.register({ name: 'tool.call.toolview', key: toolName }, FoundryRow);
        }
      });
      collapseOnce(ctx);
    }

    exports.apply = apply;
    exports.inject = inject;
    return module.exports;
  },
});
